def _collect_all_tasks(dependencies: dict[str, list[str]]) -> set[str]:
    tasks = set(dependencies)
    for blockers in dependencies.values():
        tasks.update(blockers)
    return tasks


def _build_remaining(
    tasks: set[str],
    dependencies: dict[str, list[str]],
    already_done: set[str],
) -> dict[str, set[str]]:
    return {
        task: set(dependencies.get(task, [])) - already_done
        for task in tasks
        if task not in already_done
    }


def _run_kahn(remaining: dict[str, set[str]]) -> list[list[str]]:
    batches: list[list[str]] = []
    while remaining:
