        batches.append(ready)
        completed_now = set(ready)
        remaining = {
            task: blockers - completed_now
            for task, blockers in remaining.items()
            if task not in completed_now
        }
    return batches


def plan_batches(
    dependencies: dict[str, list[str]],
    *,
    completed: set[str] | None = None,
) -> list[list[str]]:
    # Input validation
    if not isinstance(dependencies, dict):
        raise TypeError(
            f"dependencies must be a dict, got {type(dependencies).__name__}"
        )
    for key, value in dependencies.items():
        if not isinstance(key, str):
            raise TypeError(
                f"dependency keys must be strings, got {type(key).__name__!r}"
            )
        if not isinstance(value, list):
            raise TypeError(
                f"dependency values must be lists, got {type(value).__name__!r} "
                f"for key {key!r}"
            )
        for item in value:
            if not isinstance(item, str):
                raise TypeError(
                    f"dependency list items must be strings, got "
                    f"{type(item).__name__!r} in list for key {key!r}"
                )

    if completed is not None and not isinstance(completed, set):
        raise TypeError(
            f"completed must be a set or None, got {type(completed).__name__}"
        )

    already_done = set(completed) if completed else set()
    tasks = _collect_all_tasks(dependencies)
    remaining = _build_remaining(tasks, dependencies, already_done)
    return _run_kahn(remaining)

